    "curl-twisting-standing-dumbbell-biceps-curl-369":  {
                                                            "instructions":  [
                                                                                 {
                                                                                     "pl":  "Ustaw ciało stabilnie i złap ciężar lub uchwyt zgodnie z wariantem ćwiczenia.",
                                                                                     "en":  "Set your body stable and grab the weight or handle according to the exercise variation."
                                                                                 },
                                                                                 {
                                                                                     "pl":  "Napnij brzuch, ustaw łokcie blisko tułowia i rozpocznij uginanie ramion.",
                                                                                     "en":  "Brace your core, set your elbows close to your torso, and begin curling your arms."
                                                                                 },
                                                                                 {
                                                                                     "pl":  "Unieś ciężar do momentu mocnego napięcia bicepsów, bez przesuwania barków do przodu.",
                                                                                     "en":  "Lift the weight until the biceps are strongly contracted, without letting the shoulders move forward."
                                                                                 },
                                                                                 {
                                                                                     "pl":  "Powoli opuść ciężar do prawie pełnego wyprostu łokci, utrzymując kontrolę.",
                                                                                     "en":  "Slowly lower the weight to nearly full elbow extension while maintaining control."
                                                                                 }
                                                                             ],
                                                            "techniqueTips":  [
                                                                                  {
                                                                                      "pl":  "Trzymaj łokcie możliwie stabilnie; nie wypychaj ich do przodu, aby ułatwić ruch.",
                                                                                      "en":  "Keep your elbows as stable as possible; do not push them forward to make the movement easier."
                                                                                  },
                                                                                  {
                                                                                      "pl":  "Nie bujaj tułowiem — ciężar ma podnosić biceps, a nie zamach bioder.",
                                                                                      "en":  "Do not swing your torso — the biceps should lift the weight, not hip momentum."
                                                                                  },
                                                                                  {
                                                                                      "pl":  "Kontroluj nadgarstki i nie pozwalaj im zapadać się pod obciążeniem.",
                                                                                      "en":  "Control your wrists and do not let them collapse under the load."
                                                                                  },
                                                                                  {
                                                                                      "pl":  "Opuszczaj ciężar wolniej niż go podnosisz, zachowując napięcie mięśni.",
                                                                                      "en":  "Lower the weight more slowly than you lift it, maintaining muscle tension."
                                                                                  },
                                                                                  {
                                                                                      "pl":  "Prowadź hantle kontrolowanie i pilnuj, aby obie strony pracowały w tym samym tempie.",
                                                                                      "en":  "Move the dumbbells with control and make sure both sides work at the same tempo."
                                                                                  },
                                                                                  {
                                                                                      "pl":  "Rotację wykonuj z kontrolą tułowia i bioder, bez gwałtownego skręcania kręgosłupa.",
                                                                                      "en":  "Perform the rotation with control of your torso and hips, without violently twisting the spine."
                                                                                  }
                                                                              ],
                                                            "commonMistakes":  [
                                                                                   {
                                                                                       "pl":  "Bujanie tułowiem i zarzucanie ciężaru biodrami.",
                                                                                       "en":  "Swinging the torso and throwing the weight up with the hips."
                                                                                   },
                                                                                   {
                                                                                       "pl":  "Przesuwanie łokci do przodu zamiast trzymania ich stabilnie przy tułowiu.",
                                                                                       "en":  "Moving the elbows forward instead of keeping them stable near the torso."
                                                                                   },
                                                                                   {
                                                                                       "pl":  "Zbyt szybkie opuszczanie ciężaru bez kontroli fazy ekscentrycznej.",
                                                                                       "en":  "Lowering the weight too quickly without controlling the eccentric phase."
                                                                                   },
                                                                                   {
                                                                                       "pl":  "Dobranie obciążenia, które wymusza kompensacje i skraca zakres ruchu.",
                                                                                       "en":  "Selecting a load that forces compensation and shortens the range of motion."
                                                                                   }
                                                                               ]
                                                        },
