    "deadlift-barbell-deadlift-371":  {
                                          "instructions":  [
                                                               {
                                                                   "pl":  "Ustaw stopy stabilnie, napnij brzuch i przygotuj pozycję bioder.",
                                                                   "en":  "Set your feet stable, brace your core, and prepare your hip position."
                                                               },
                                                               {
                                                                   "pl":  "Cofnij biodra, schodząc w dół po kontrolowanym torze przy neutralnych plecach.",
                                                                   "en":  "Push your hips back as you descend along a controlled path with a neutral back."
                                                               },
                                                               {
                                                                   "pl":  "Zatrzymaj zejście, gdy czujesz mocne rozciągnięcie tylnej taśmy albo gdy tracisz neutralną pozycję.",
                                                                   "en":  "Stop the descent when you feel a strong stretch in the posterior chain or when you lose a neutral position."
                                                               },
                                                               {
                                                                   "pl":  "Wróć do góry przez wyprost bioder, prowadząc ruch pośladkami i tyłem uda.",
                                                                   "en":  "Return upward through hip extension, driving the movement with the glutes and hamstrings."
                                                               }
                                                           ],
                                          "techniqueTips":  [
                                                                {
                                                                    "pl":  "Ruch zacznij od cofnięcia bioder, a nie od zaokrąglania pleców.",
                                                                    "en":  "Start the movement by pushing the hips back, not by rounding your back."
                                                                },
                                                                {
                                                                    "pl":  "Utrzymuj neutralny kręgosłup i napięty brzuch przez całe powtórzenie.",
                                                                    "en":  "Maintain a neutral spine and a braced core throughout the entire rep."
                                                                },
                                                                {
                                                                    "pl":  "Prowadź ciężar blisko ciała, aby nie przeciążać odcinka lędźwiowego.",
                                                                    "en":  "Keep the load close to your body to avoid overloading the lower back."
                                                                },
                                                                {
                                                                    "pl":  "Kończ ruch mocnym wyprostem bioder i napięciem pośladków, bez przeprostu w plecach.",
                                                                    "en":  "Finish with a strong hip extension and glute squeeze, without hyperextending your back."
                                                                },
                                                                {
                                                                    "pl":  "Trzymaj gryf symetrycznie i prowadź go po możliwie stabilnym, powtarzalnym torze.",
                                                                    "en":  "Hold the bar symmetrically and move it along the most stable, repeatable path possible."
                                                                }
                                                            ],
                                          "commonMistakes":  [
                                                                 {
                                                                     "pl":  "Zaokrąglanie odcinka lędźwiowego zamiast utrzymania neutralnego kręgosłupa.",
                                                                     "en":  "Rounding the lower back instead of maintaining a neutral spine."
                                                                 },
                                                                 {
                                                                     "pl":  "Oddalanie ciężaru od ciała i utrata napięcia najszerszych grzbietu.",
                                                                     "en":  "Letting the load drift away from the body and losing lat tension."
                                                                 },
                                                                 {
                                                                     "pl":  "Rozpoczynanie ruchu od ciągnięcia plecami zamiast pracy bioder i nóg.",
                                                                     "en":  "Starting the movement by pulling with the back instead of using the hips and legs."
                                                                 },
                                                                 {
                                                                     "pl":  "Dobranie obciążenia, które wymusza kompensacje i skraca zakres ruchu.",
                                                                     "en":  "Selecting a load that forces compensation and shortens the range of motion."
                                                                 }
                                                             ]
                                      },
