    "hip-raise-barbell-hip-thrust-on-floor-407":  {
                                                      "instructions":  [
                                                                           {
                                                                               "pl":  "Przyjmij pozycję startową i ustaw biodra tak, aby miednica była stabilna.",
                                                                               "en":  "Take the starting position and set your hips so the pelvis is stable."
                                                                           },
                                                                           {
                                                                               "pl":  "Napnij brzuch oraz pośladki i rozpocznij ruch w stawie biodrowym.",
                                                                               "en":  "Brace your core and glutes, then begin the movement at the hip joint."
                                                                           },
                                                                           {
                                                                               "pl":  "Doprowadź nogę albo biodra do zakresu, w którym nadal kontrolujesz tułów.",
                                                                               "en":  "Move the leg or hips into a range where you can still control your torso."
                                                                           },
                                                                           {
                                                                               "pl":  "Wróć powoli do pozycji startowej, utrzymując napięcie mięśni pośladkowych.",
                                                                               "en":  "Return slowly to the starting position while maintaining glute tension."
                                                                           }
                                                                       ],
                                                      "techniqueTips":  [
                                                                            {
                                                                                "pl":  "Prowadź ruch z biodra, nie z odcinka lędźwiowego kręgosłupa.",
                                                                                "en":  "Drive the movement from the hip, not from the lumbar spine."
                                                                            },
                                                                            {
                                                                                "pl":  "Utrzymuj miednicę stabilnie; nie przekręcaj jej, żeby sztucznie zwiększyć zakres.",
                                                                                "en":  "Keep the pelvis stable; do not rotate it to artificially increase the range."
                                                                            },
                                                                            {
                                                                                "pl":  "W końcowej fazie świadomie dopnij pośladek po stronie pracującej.",
                                                                                "en":  "Consciously squeeze the glute on the working side at the end of the movement."
                                                                            },
                                                                            {
                                                                                "pl":  "Kontroluj powrót i nie pozwalaj nodze opadać bez napięcia.",
                                                                                "en":  "Control the return and do not let the leg drop without tension."
                                                                            },
                                                                            {
                                                                                "pl":  "Trzymaj gryf symetrycznie i prowadź go po możliwie stabilnym, powtarzalnym torze.",
                                                                                "en":  "Hold the bar symmetrically and move it along the most stable, repeatable path possible."
                                                                            },
                                                                            {
                                                                                "pl":  "Dociśnij punkty podparcia do podłoża lub ławki, żeby ruch był stabilny.",
                                                                                "en":  "Press your support points into the floor or bench so the movement stays stable."
                                                                            }
                                                                        ],
                                                      "commonMistakes":  [
                                                                             {
                                                                                 "pl":  "Przeprost w odcinku lędźwiowym zamiast końcowego dopięcia pośladków.",
                                                                                 "en":  "Hyperextending the lower back instead of finishing with a glute squeeze."
                                                                             },
                                                                             {
                                                                                 "pl":  "Ustawienie stóp zbyt daleko lub zbyt blisko, przez co pracę przejmują uda albo plecy.",
                                                                                 "en":  "Setting the feet too far or too close, causing the thighs or back to take over."
                                                                             },
                                                                             {
                                                                                 "pl":  "Zapadanie kolan do środka podczas wypychania bioder.",
                                                                                 "en":  "Letting the knees collapse inward while driving the hips up."
                                                                             },
                                                                             {
                                                                                 "pl":  "Dobranie obciążenia, które wymusza kompensacje i skraca zakres ruchu.",
                                                                                 "en":  "Selecting a load that forces compensation and shortens the range of motion."
                                                                             }
                                                                         ]
                                                  },
