    "lateral-raise-45-degree-cable-external-rotation-536":  {
                                                                "instructions":  [
                                                                                     {
                                                                                         "pl":  "Ustaw stabilną pozycję, napnij brzuch i przygotuj łopatki.",
                                                                                         "en":  "Set a stable position, brace your core, and prepare your shoulder blades."
                                                                                     },
                                                                                     {
                                                                                         "pl":  "Rozpocznij ruch ramieniem zgodnie z kierunkiem ćwiczenia, bez kołysania tułowiem.",
                                                                                         "en":  "Begin the arm movement in the direction of the exercise, without swinging your torso."
                                                                                     },
                                                                                     {
                                                                                         "pl":  "Doprowadź ramię do kontrolowanego zakresu, utrzymując bark nisko i stabilnie.",
                                                                                         "en":  "Move the arm into a controlled range while keeping the shoulder low and stable."
                                                                                     },
                                                                                     {
                                                                                         "pl":  "Wróć wolno do pozycji startowej, cały czas kontrolując łopatkę i nadgarstek.",
                                                                                         "en":  "Return slowly to the starting position while controlling the shoulder blade and wrist the entire time."
                                                                                     }
                                                                                 ],
                                                                "techniqueTips":  [
                                                                                      {
                                                                                          "pl":  "Trzymaj żebra opuszczone i nie wyginaj pleców, żeby podnieść ciężar wyżej.",
                                                                                          "en":  "Keep your ribs down and do not arch your back to lift the weight higher."
                                                                                      },
                                                                                      {
                                                                                          "pl":  "Nie unoś barków do uszu; szyja powinna pozostać możliwie luźna.",
                                                                                          "en":  "Do not shrug your shoulders toward your ears; keep your neck as relaxed as possible."
                                                                                      },
                                                                                      {
                                                                                          "pl":  "Prowadź ruch płynnie i kontroluj końcowy zakres, szczególnie przy rotacjach.",
                                                                                          "en":  "Move smoothly and control the end range, especially during rotations."
                                                                                      },
                                                                                      {
                                                                                          "pl":  "Dobierz lekki ciężar, jeśli ćwiczenie dotyczy rotatorów albo prehabilitacji barków.",
                                                                                          "en":  "Choose a light load if the exercise targets the rotator cuff or shoulder prehab."
                                                                                      },
                                                                                      {
                                                                                          "pl":  "Ustaw się tak, aby linka pracowała w jednej płaszczyźnie z ruchem, bez szarpania stosu.",
                                                                                          "en":  "Position yourself so the cable moves in the same plane as the movement, without jerking the stack."
                                                                                      },
                                                                                      {
                                                                                          "pl":  "Rotację wykonuj z kontrolą tułowia i bioder, bez gwałtownego skręcania kręgosłupa.",
                                                                                          "en":  "Perform the rotation with control of your torso and hips, without violently twisting the spine."
                                                                                      }
                                                                                  ],
                                                                "commonMistakes":  [
                                                                                       {
                                                                                           "pl":  "Używanie zbyt dużego oporu i kompensowanie ruchem tułowia.",
                                                                                           "en":  "Using too much resistance and compensating with torso movement."
                                                                                       },
                                                                                       {
                                                                                           "pl":  "Odsuwanie łokcia od stabilnej pozycji zamiast izolowania rotacji w barku.",
                                                                                           "en":  "Moving the elbow away from a stable position instead of isolating shoulder rotation."
                                                                                       },
                                                                                       {
                                                                                           "pl":  "Ustawienie wyciągu niezgodnie z kierunkiem ruchu, co zmienia pracę docelowych mięśni.",
                                                                                           "en":  "Setting the cable pulley out of line with the movement direction, changing the work of the target muscles."
                                                                                       },
                                                                                       {
                                                                                           "pl":  "Pozwalanie, aby stos ciężaru opadał bez kontroli między powtórzeniami.",
                                                                                           "en":  "Letting the weight stack drop without control between reps."
                                                                                       }
                                                                                   ]
                                                            },
