    "lunge-alternating-barbell-forward-lunge-608":  {
                                                        "instructions":  [
                                                                             {
                                                                                 "pl":  "Ustaw stopy i tułów zgodnie z wariantem ćwiczenia, a ciężar rozłóż równomiernie na aktywnej stopie.",
                                                                                 "en":  "Set your feet and torso according to the exercise variation and distribute the load evenly over the active foot."
                                                                             },
                                                                             {
                                                                                 "pl":  "Weź wdech, napnij brzuch i rozpocznij zejście, kontrolując kolana oraz ustawienie miednicy.",
                                                                                 "en":  "Inhale, brace your core, and begin descending while controlling your knees and pelvis position."
                                                                             },
                                                                             {
                                                                                 "pl":  "Zejdź do zakresu, w którym zachowujesz równowagę i napięcie mięśni nóg.",
                                                                                 "en":  "Descend into a range where you maintain balance and leg muscle tension."
                                                                             },
                                                                             {
                                                                                 "pl":  "Odepchnij się od podłoża i wróć do pozycji startowej bez kołysania tułowiem.",
                                                                                 "en":  "Push away from the floor and return to the starting position without swaying your torso."
                                                                             }
                                                                         ],
                                                        "techniqueTips":  [
                                                                              {
                                                                                  "pl":  "Trzymaj stopę aktywnie dociśniętą do podłoża: pięta, paluch i zewnętrzna krawędź stopy.",
                                                                                  "en":  "Keep the foot actively pressed into the floor: heel, big toe, and outer edge of the foot."
                                                                              },
                                                                              {
                                                                                  "pl":  "Kolano prowadź w linii z palcami stopy, bez zapadania do środka.",
                                                                                  "en":  "Keep the knee tracking in line with the toes, without letting it collapse inward."
                                                                              },
                                                                              {
                                                                                  "pl":  "Utrzymuj napięty brzuch i neutralne ustawienie miednicy.",
                                                                                  "en":  "Keep your core braced and your pelvis neutral."
                                                                              },
                                                                              {
                                                                                  "pl":  "Schodź tylko tak nisko, jak pozwala stabilna pozycja bioder, kolan i stóp.",
                                                                                  "en":  "Go only as low as your hips, knees, and feet can remain stable."
                                                                              },
                                                                              {
                                                                                  "pl":  "Trzymaj gryf symetrycznie i prowadź go po możliwie stabilnym, powtarzalnym torze.",
                                                                                  "en":  "Hold the bar symmetrically and move it along the most stable, repeatable path possible."
                                                                              },
                                                                              {
                                                                                  "pl":  "W wariancie jednostronnym porównuj obie strony i nie nadrabiaj słabszej strony rozpędem.",
                                                                                  "en":  "In unilateral variations, compare both sides and do not compensate for the weaker side with momentum."
                                                                              }
                                                                          ],
                                                        "commonMistakes":  [
                                                                               {
                                                                                   "pl":  "Zapadanie kolana nogi wykrocznej do środka.",
                                                                                   "en":  "Letting the lead-leg knee collapse inward."
                                                                               },
                                                                               {
                                                                                   "pl":  "Odpychanie się głównie tylną nogą zamiast kontrolowanej pracy nogi prowadzącej.",
                                                                                   "en":  "Pushing mainly with the rear leg instead of controlled work from the lead leg."
                                                                               },
                                                                               {
                                                                                   "pl":  "Pochylanie tułowia bez utrzymania napięcia brzucha.",
                                                                                   "en":  "Leaning the torso without maintaining core tension."
                                                                               },
                                                                               {
                                                                                   "pl":  "Dobranie obciążenia, które wymusza kompensacje i skraca zakres ruchu.",
                                                                                   "en":  "Selecting a load that forces compensation and shortens the range of motion."
                                                                               }
                                                                           ]
                                                    },
