    "olympic-lift-barbell-hang-power-clean-699":  {
                                                      "instructions":  [
                                                                           {
                                                                               "pl":  "Ustaw stopy, chwyt i pozycję bioder zgodnie z wariantem ćwiczenia.",
                                                                               "en":  "Set your feet, grip, and hip position according to the exercise variation."
                                                                           },
                                                                           {
                                                                               "pl":  "Napnij tułów i rozpocznij ruch płynnie, utrzymując ciężar blisko ciała.",
                                                                               "en":  "Brace your torso and begin the movement smoothly, keeping the load close to your body."
                                                                           },
                                                                           {
                                                                               "pl":  "Dynamicznie wyprostuj biodra i kolana, a następnie przejdź pod ciężar lub doprowadź go do pozycji końcowej.",
                                                                               "en":  "Dynamically extend your hips and knees, then move under the load or guide it to the final position."
                                                                           },
                                                                           {
                                                                               "pl":  "Ustabilizuj pozycję końcową, po czym kontrolowanie wróć do startu.",
                                                                               "en":  "Stabilize the final position, then return to the start with control."
                                                                           }
                                                                       ],
                                                      "techniqueTips":  [
                                                                            {
                                                                                "pl":  "Zacznij od stabilnego ustawienia pleców i bioder; nie ciągnij ciężaru samymi rękami.",
                                                                                "en":  "Start with a stable back and hip position; do not pull the load with your arms alone."
                                                                            },
                                                                            {
                                                                                "pl":  "Moc generuj z nóg i bioder, a ramiona wykorzystuj do prowadzenia ciężaru.",
                                                                                "en":  "Generate power from your legs and hips, and use your arms to guide the load."
                                                                            },
                                                                            {
                                                                                "pl":  "Trzymaj ciężar blisko ciała, aby nie tracić toru i równowagi.",
                                                                                "en":  "Keep the load close to your body to maintain the path and balance."
                                                                            },
                                                                            {
                                                                                "pl":  "Ćwiczenia dynamiczne wykonuj technicznie; przy utracie pozycji zmniejsz obciążenie.",
                                                                                "en":  "Perform dynamic exercises with sound technique; reduce the load if you lose position."
                                                                            },
                                                                            {
                                                                                "pl":  "Trzymaj gryf symetrycznie i prowadź go po możliwie stabilnym, powtarzalnym torze.",
                                                                                "en":  "Hold the bar symmetrically and move it along the most stable, repeatable path possible."
                                                                            }
                                                                        ],
                                                      "commonMistakes":  [
                                                                             {
                                                                                 "pl":  "Zaczynanie ruchu od ramion zamiast od mocnego wyprostu bioder i nóg.",
                                                                                 "en":  "Starting the movement with the arms instead of a strong hip and leg extension."
                                                                             },
                                                                             {
                                                                                 "pl":  "Przyjmowanie ciężaru na sztywnych nogach bez stabilnej pozycji końcowej.",
                                                                                 "en":  "Receiving the load on stiff legs without a stable final position."
                                                                             },
                                                                             {
                                                                                 "pl":  "Oddalanie ciężaru od ciała i tracenie pionowego toru ruchu.",
                                                                                 "en":  "Letting the load drift away from the body and losing the vertical movement path."
                                                                             },
                                                                             {
                                                                                 "pl":  "Dobranie obciążenia, które wymusza kompensacje i skraca zakres ruchu.",
                                                                                 "en":  "Selecting a load that forces compensation and shortens the range of motion."
                                                                             }
                                                                         ]
                                                  },
