    "push-up-medicine-ball-push-up-967":  {
                                              "instructions":  [
                                                                   {
                                                                       "pl":  "Przyjmij stabilną pozycję startową i ustaw dłonie lub chwyt zgodnie z wariantem ćwiczenia.",
                                                                       "en":  "Take a stable starting position and set your hands or grip according to the exercise variation."
                                                                   },
                                                                   {
                                                                       "pl":  "Weź wdech, napnij brzuch i ustaw łopatki tak, aby barki były stabilne.",
                                                                       "en":  "Inhale, brace your core, and set your shoulder blades so the shoulders are stable."
                                                                   },
                                                                   {
                                                                       "pl":  "Wypchnij ciężar albo ciało po kontrolowanym torze, utrzymując stałe napięcie klatki, barków i tricepsów.",
                                                                       "en":  "Press the load or body along a controlled path while maintaining constant tension in the chest, shoulders, and triceps."
                                                                   },
                                                                   {
                                                                       "pl":  "Wróć wolno do pozycji startowej, zatrzymując ruch zanim stracisz napięcie lub pozycję barków.",
                                                                       "en":  "Return slowly to the starting position, stopping the movement before you lose tension or shoulder position."
                                                                   }
                                                               ],
                                              "techniqueTips":  [
                                                                    {
                                                                        "pl":  "Ustaw łopatki stabilnie i nie pozwalaj barkom uciekać do uszu.",
                                                                        "en":  "Set your shoulder blades stable and do not let your shoulders creep toward your ears."
                                                                    },
                                                                    {
                                                                        "pl":  "Prowadź łokcie pod kontrolą; nie rozszerzaj ich agresywnie na boki.",
                                                                        "en":  "Keep the elbows controlled; do not flare them aggressively out to the sides."
                                                                    },
                                                                    {
                                                                        "pl":  "Napnij brzuch i pośladki, aby nie wyginać nadmiernie odcinka lędźwiowego.",
                                                                        "en":  "Brace your core and glutes to avoid excessive arching in the lower back."
                                                                    },
                                                                    {
                                                                        "pl":  "Kończ ruch mocnym dopchnięciem, ale bez gwałtownego blokowania stawów.",
                                                                        "en":  "Finish the movement with a strong press, but without aggressively locking the joints."
                                                                    }
                                                                ],
                                              "commonMistakes":  [
                                                                     {
                                                                         "pl":  "Opadanie bioder albo wypychanie pośladków zamiast utrzymania jednej linii ciała.",
                                                                         "en":  "Letting the hips drop or pushing the glutes up instead of maintaining one body line."
                                                                     },
                                                                     {
                                                                         "pl":  "Rozstawianie łokci zbyt szeroko i przeciążanie barków.",
                                                                         "en":  "Flaring the elbows too wide and overloading the shoulders."
                                                                     },
                                                                     {
                                                                         "pl":  "Skracanie zakresu ruchu lub zapadanie się klatki między łopatkami.",
                                                                         "en":  "Shortening the range of motion or letting the chest collapse between the shoulder blades."
                                                                     },
                                                                     {
                                                                         "pl":  "Utrata napięcia brzucha i pośladków w trakcie serii.",
                                                                         "en":  "Losing core and glute tension during the set."
                                                                     }
                                                                 ]
                                          },
